ob_start();set_exception_handler(static function(Throwable $e){fwrite(STDERR,'FAIL '.$e->getMessage().PHP_EOL);exit(1);});
function check(bool $ok,string $label):void{if(!$ok){throw new RuntimeException($label);}echo 'PASS '.$label.PHP_EOL;}
$marker='remove-check-'.bin2hex(random_bytes(4));$ids=[];$sessions=[];$jars=[];$temps=[];$eventId=null;$password='Test-'.bin2hex(random_bytes(14));
$base=base_url();if(str_starts_with($base,'/')){$base='http://localhost'.$base;}if(!in_array(parse_url($base,PHP_URL_HOST),['localhost','127.0.0.1'],true)){throw new RuntimeException('Hanya lokal');}
$request=static function(string $route,?array $post=null,?string $cookie=null,?string $jar=null)use($base):array{$headers=[];$ch=curl_init(rtrim($base,'/').'/'.$route);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_TIMEOUT=>15,CURLOPT_HEADERFUNCTION=>static function($ch,$line)use(&$headers){$p=explode(':',$line,2);if(count($p)===2){$headers[strtolower(trim($p[0]))]=trim($p[1]);}return strlen($line);}]);if($cookie){curl_setopt($ch,CURLOPT_COOKIE,$cookie);}if($jar){curl_setopt($ch,CURLOPT_COOKIEFILE,$jar);curl_setopt($ch,CURLOPT_COOKIEJAR,$jar);}if($post!==null){curl_setopt($ch,CURLOPT_POST,true);curl_setopt($ch,CURLOPT_POSTFIELDS,$post);}$body=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_RESPONSE_CODE);curl_close($ch);return [$code,$body,$headers];};
try{
check(!panel_query("SHOW TABLES LIKE 'student_accounts'")->fetchColumn(),'Tabel penghubung akun siswa tidak ada');
