foreach(['admin','staf_bkk'] as $role){$username=$marker.'-'.$role;panel_query('INSERT INTO users(nama,username,email,password_hash,role,aktif) VALUES(:nama,:username,:email,:hash,:role,1)',['nama'=>$username,'username'=>$username,'email'=>$username.'@example.test','hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>$role]);$ids[]=(int)db()->lastInsertId();$jar=sys_get_temp_dir().'/'.$username.'.cookie';$jars[]=$jar;[$code,$body]=$request('auth/login.php',null,null,$jar);preg_match('/name="csrf_token" value="([^"]+)"/',$body,$m);[$code,$body,$headers]=$request('auth/proses-login.php',['csrf_token'=>$m[1],'username'=>$username,'password'=>$password],null,$jar);check($code===303&&str_ends_with($headers['location']??'','/panel/index.php'),'Login '.$role.' mengarah ke panel');}
$jar=$jars[1];[$code,$body]=$request('panel/peserta/',null,null,$jar);preg_match('/name="csrf_token" value="([^"]+)"/',$body,$m);$token=$m[1];check($code===200&&str_contains($body,'Data peserta')&&!str_contains($body,'Akun peserta'),'Pengguna melihat Data Peserta tanpa fitur akun');
[$code,$xlsx]=$request('panel/peserta/template.php',null,null,$jar);$file=sys_get_temp_dir().'/'.$marker.'.xlsx';$temps[]=$file;file_put_contents($file,$xlsx);$zip=new PharData($file);$xml=$zip['xl/worksheets/sheet1.xml']->getContent();$node=simplexml_load_string($xml);check(count($node->xpath('//*[local-name()="row"]/*[local-name()="c"]'))===10,'Template peserta memuat 10 kolom');
$values=[$marker.'-1','Peserta uji satu','Kelompok A','Bidang uji','2025',$marker,'081234567890',$marker.'@example.test','',''];$cells='';foreach($values as $i=>$value){$cells.='<c r="'.chr(65+$i).'2" t="inlineStr"><is><t>'.htmlspecialchars($value,ENT_XML1).'</t></is></c>';}$zip['xl/worksheets/sheet1.xml']=str_replace('</sheetData>','<row r="2">'.$cells.'</row></sheetData>',$xml);unset($zip);
$countUsers=(int)panel_query('SELECT COUNT(*) FROM users')->fetchColumn();[$code]=$request('panel/peserta/',['csrf_token'=>$token,'aksi'=>'impor','excel'=>new CURLFile($file,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','peserta.xlsx')],null,$jar);check($code===303&&(int)panel_query('SELECT COUNT(*) FROM siswa WHERE nis=:nis',['nis'=>$marker.'-1'])->fetchColumn()===1,'Impor Excel menyimpan peserta kegiatan');check((int)panel_query('SELECT COUNT(*) FROM users')->fetchColumn()===$countUsers,'Impor peserta tidak membuat akun login');
[$code]=$request('panel/peserta/',['csrf_token'=>$token,'nis'=>$marker.'-2','nama'=>'Peserta uji dua','kelas'=>'Kelompok A','angkatan'=>'2025','kelas_industri'=>$marker],null,$jar);check($code===303,'Tambah manual peserta berhasil');
[$code]=$request('panel/absensi/',['csrf_token'=>$token,'judul'=>$marker,'tanggal'=>'2026-10-24','angkatan'=>'2025','kelas_industri'=>$marker],null,$jar);$eventId=(int)panel_query('SELECT id FROM attendance_events WHERE judul=:judul',['judul'=>$marker])->fetchColumn();check($code===303&&$eventId>0,'Kegiatan mengambil daftar peserta');
$records=[];foreach(panel_query('SELECT id FROM attendance_records WHERE event_id=:id ORDER BY nama,id',['id'=>$eventId])->fetchAll(PDO::FETCH_COLUMN) as $i=>$id){$records[$id]=['status'=>$i?'izin':'hadir','keterangan'=>'Uji'];}attendance_save($eventId,1,1,$records,$ids[1]);
foreach(['panel/absensi/detail.php?id='.$eventId,'panel/absensi/rekap.php?kelas_industri='.$marker,'panel/capaian-pembelajaran/','panel/pemateri/','panel/absensi/publikasi.php?id='.$eventId] as $route){[$code,$body]=$request($route,null,null,$jar);check($code===200,'Halaman kegiatan tetap berjalan: '.$route);}
foreach(['peserta','absensi','rekap','capaian','pemateri'] as $type){[$code,$body]=$request('panel/ekspor.php?jenis='.$type.'&kelas_industri='.$marker,null,null,$jar);check($code===200&&str_starts_with($body,'PK'),'Ekspor Excel '.$type.' tetap berjalan');}
foreach(['siswa/','siswa/index.php','siswa/akun.php','panel/siswa/akun.php?id=1','panel/peserta/akun.php?id=1'] as $route){[$code]=$request($route);check($code===404,'URL akun/ruang siswa dihapus: '.$route);}
foreach(['','kegiatan.php','auth/login.php'] as $route){[$code,$body]=$request($route);check($code===200&&!str_contains($body,'Login Siswa')&&!str_contains($body,'Login Peserta')&&!str_contains($body,'Akun siswa'),'Publik tanpa tombol/fitur akun siswa: '.$route);}
[$code,$body]=$request('panel/pengguna/',null,null,$jars[0]);check($code===200&&!str_contains($body,'>Siswa<'),'Pengelolaan pengguna hanya akun pengelola');
[$code]=$request('panel/peserta/');check($code===302,'Data peserta tetap memerlukan login pengelola');
}finally{
if($eventId){panel_query('DELETE FROM attendance_events WHERE id=:id',['id'=>$eventId]);}panel_query('DELETE FROM siswa WHERE nis IN (:one,:two)',['one'=>$marker.'-1','two'=>$marker.'-2']);foreach($ids as $id){panel_query('DELETE FROM users WHERE id=:id',['id'=>$id]);}
foreach($jars as $jar){if(is_file($jar)){foreach(file($jar) as $line){$p=explode("\t",trim($line));if(count($p)===7&&$p[5]==='bkk_session'&&preg_match('/^[a-zA-Z0-9,-]+$/D',$p[6])){$sessions[]=APP_ROOT.'/storage/sessions/sess_'.$p[6];}}unlink($jar);}}foreach(array_merge($temps,$sessions) as $path){if(is_file($path)){unlink($path);}}
}